LOGIN_CSS = '<style>\n.bk{display:none}\nmain{min-height:100dvh;box-sizing:border-box;display:flex;align-items:center;justify-content:center;padding:24px}\n.login{width:100%;max-width:340px;text-align:center;padding:40px 28px 30px;border-radius:30px;background:var(--glass);-webkit-backdrop-filter:var(--blur);backdrop-filter:var(--blur);\n  box-shadow:none}\n.login .mk{width:68px;height:68px;margin:0 auto 18px;border-radius:16px;box-shadow:0 1px 3px rgba(24,44,64,.10),0 0 0 .5px rgba(24,44,64,.14)}\n.login h1{font-size:30px;letter-spacing:.32em;margin:0 0 4px .32em} .login .sub{color:var(--faint);font-size:13px;letter-spacing:.06em;margin:0 0 28px}\n.login input{box-sizing:border-box;width:100%;font:inherit;font-size:17px;color:var(--ink);background:var(--glass);border:0;border-radius:999px;padding:12px 18px;margin:0 0 12px;outline:none;\n  background:var(--knob-in);box-shadow:none;transition:box-shadow .2s,background .2s}\n.login input::placeholder{color:var(--faint)}\n.login input:focus{background:var(--glass-hi);box-shadow:none}\n.login button{width:100%;font:inherit;font-size:17px;font-weight:500;letter-spacing:.3em;color:var(--acc);border:0;border-radius:999px;padding:12px;margin-top:8px;cursor:pointer;\n  background:rgba(44,74,116,.12);box-shadow:none}\n.login button:active{transform:scale(.98)}\n.err{color:var(--red);font-size:14px;margin:-12px 0 16px}\n</style>'
